def lookup_commercial_model(raw_identifier: str) -> Optional[Dict[str, Any]]:
    """
    Looks up a device identifier (hardware model code, marketing tag, user agent snippet,
    or commercial pawn string) against the commercial smartphone database.
    """
    if not raw_identifier:
        return None

    raw_str = str(raw_identifier).strip()
    cleaned = raw_str.upper()

    # 1. Exact match in database
    if cleaned in COMMERCIAL_DEVICE_DATABASE:
        item = COMMERCIAL_DEVICE_DATABASE[cleaned]
        return {
            "brand": item["brand"],
            "model": item["model"],
            "market_name": f"{item['brand']} {item['model']}",
            "soc": item["soc"],
            "ram_gb": item["ram_gb"],
            "storage_gb": item["storage_gb"],
            "code": cleaned
        }

    # 2. Substring matching for model codes (e.g. inside user agent or ADB model strings)
    for code, item in COMMERCIAL_DEVICE_DATABASE.items():
        if len(code) >= 4 and code in cleaned:
            return {
                "brand": item["brand"],
                "model": item["model"],
                "market_name": f"{item['brand']} {item['model']}",
                "soc": item["soc"],
                "ram_gb": item["ram_gb"],
                "storage_gb": item["storage_gb"],
                "code": code
            }

    # 3. Regex search for hardware vendor code patterns
    # Oppo CPHxxxx
    oppo_match = re.search(r"CPH\d{4}", cleaned)
    if oppo_match and oppo_match.group(0) in COMMERCIAL_DEVICE_DATABASE:
        code = oppo_match.group(0)
        item = COMMERCIAL_DEVICE_DATABASE[code]
        return {
            "brand": item["brand"],
            "model": item["model"],
            "market_name": f"{item['brand']} {item['model']}",
            "soc": item["soc"],
            "ram_gb": item["ram_gb"],
            "storage_gb": item["storage_gb"],
            "code": code
        }

    # Samsung SM-Xxxx (with or without regional suffix e.g. SM-A055F/DS -> SM-A055F)
    samsung_match = re.search(r"SM-[A-Z0-9]+", cleaned)
    if samsung_match:
        cand = samsung_match.group(0)
        if cand in COMMERCIAL_DEVICE_DATABASE:
            item = COMMERCIAL_DEVICE_DATABASE[cand]
            return {
                "brand": item["brand"],
                "model": item["model"],
                "market_name": f"{item['brand']} {item['model']}",
                "soc": item["soc"],
                "ram_gb": item["ram_gb"],
                "storage_gb": item["storage_gb"],
                "code": cand
            }
        for code, item in COMMERCIAL_DEVICE_DATABASE.items():
            if code.startswith(cand[:7]):
                return {
                    "brand": item["brand"],
                    "model": item["model"],
                    "market_name": f"{item['brand']} {item['model']}",
                    "soc": item["soc"],
                    "ram_gb": item["ram_gb"],
                    "storage_gb": item["storage_gb"],
                    "code": code
                }

    # Realme RMXxxxx
    realme_match = re.search(r"RMX\d{4}", cleaned)
    if realme_match and realme_match.group(0) in COMMERCIAL_DEVICE_DATABASE:
        code = realme_match.group(0)
        item = COMMERCIAL_DEVICE_DATABASE[code]
        return {
            "brand": item["brand"],
            "model": item["model"],
            "market_name": f"{item['brand']} {item['model']}",
            "soc": item["soc"],
            "ram_gb": item["ram_gb"],
            "storage_gb": item["storage_gb"],
            "code": code
        }

    # Vivo Vxxxx
    vivo_match = re.search(r"V\d{4}[A-Z]?", cleaned)
    if vivo_match and vivo_match.group(0) in COMMERCIAL_DEVICE_DATABASE:
        code = vivo_match.group(0)
        item = COMMERCIAL_DEVICE_DATABASE[code]
        return {
            "brand": item["brand"],
            "model": item["model"],
            "market_name": f"{item['brand']} {item['model']}",
            "soc": item["soc"],
            "ram_gb": item["ram_gb"],
            "storage_gb": item["storage_gb"],
            "code": code
        }

    # Infinix Xxxx
    infinix_match = re.search(r"X\d{3,4}[A-Z0-9]?", cleaned)
    if infinix_match and infinix_match.group(0) in COMMERCIAL_DEVICE_DATABASE:
        code = infinix_match.group(0)
        item = COMMERCIAL_DEVICE_DATABASE[code]
        return {
            "brand": item["brand"],
            "model": item["model"],
            "market_name": f"{item['brand']} {item['model']}",
            "soc": item["soc"],
            "ram_gb": item["ram_gb"],
            "storage_gb": item["storage_gb"],
            "code": code
        }

    # Apple iPhone Machine ID (e.g. iPhone14,5)
    apple_match = re.search(r"IPHONE\d+,\d+", cleaned)
    if apple_match and apple_match.group(0) in COMMERCIAL_DEVICE_DATABASE:
        code = apple_match.group(0)
        item = COMMERCIAL_DEVICE_DATABASE[code]
        return {
            "brand": item["brand"],
            "model": item["model"],
            "market_name": f"{item['brand']} {item['model']}",
            "soc": item["soc"],
            "ram_gb": item["ram_gb"],
            "storage_gb": item["storage_gb"],
            "code": code
        }

    # 4. Fallback search by commercial marketing name or pawn string
    normalized_query = re.sub(r"[-_]", " ", cleaned)
    # Remove RAM/ROM tokens like "8 256", "128GB", "4G", "5G", "1TB"
    clean_tokens = [t for t in normalized_query.split() if not re.match(r"^(\d+GB|\d+TB|\d+/\d+|\d+G|\d+)$", t)]
    clean_name = " ".join(clean_tokens)

    # First pass: try matching both Brand AND Model if brand is present in the query
    detected_brand = None
    for b in ["SAMSUNG", "OPPO", "XIAOMI", "REDMI", "POCO", "VIVO", "REALME", "INFINIX", "TECNO", "ITEL", "ASUS", "HUAWEI", "APPLE", "IPHONE"]:
        if b in clean_tokens or b in clean_name:
            detected_brand = b
            break

    if detected_brand:
        # Match within detected brand first
        for code, item in COMMERCIAL_DEVICE_DATABASE.items():
            b_item = item["brand"].upper()
            is_brand_match = (detected_brand in b_item) or                              (detected_brand in ["REDMI", "POCO"] and b_item in ["XIAOMI", "POCO"]) or                              (detected_brand == "IPHONE" and b_item == "APPLE")
            if is_brand_match:
                market_str = f"{item['brand']} {item['model']}".upper()
                model_str = item['model'].upper()
                # Check model tokens
                model_tokens = [t for t in clean_tokens if t not in ["SAMSUNG", "OPPO", "XIAOMI", "REDMI", "POCO", "VIVO", "REALME", "INFINIX", "TECNO", "ITEL", "ASUS", "HUAWEI", "APPLE", "IPHONE", "GALAXY"]]
                if clean_name in market_str or market_str in clean_name:
                    return {
                        "brand": item["brand"],
                        "model": item["model"],
                        "market_name": f"{item['brand']} {item['model']}",
                        "soc": item["soc"],
                        "ram_gb": item["ram_gb"],
                        "storage_gb": item["storage_gb"],
                        "code": code
                    }
                if model_tokens and all(mt in model_str for mt in model_tokens):
                    return {
                        "brand": item["brand"],
                        "model": item["model"],
                        "market_name": f"{item['brand']} {item['model']}",
                        "soc": item["soc"],
                        "ram_gb": item["ram_gb"],
                        "storage_gb": item["storage_gb"],
                        "code": code
                    }

    # Second pass: generic match against full market_name
    for code, item in COMMERCIAL_DEVICE_DATABASE.items():
        market_str = f"{item['brand']} {item['model']}".upper()
        if clean_name and (clean_name in market_str or market_str in clean_name):
            return {
                "brand": item["brand"],
                "model": item["model"],
                "market_name": f"{item['brand']} {item['model']}",
                "soc": item["soc"],
                "ram_gb": item["ram_gb"],
                "storage_gb": item["storage_gb"],
                "code": code
            }

    return None
